def f(inp):
    H=len(inp); W=len(inp[0])
    A=np.array(inp)
    box=(A==5)
    R0,R1=box.sum(axis=1).nonzero()[0][0],box.sum(axis=1).nonzero()[0][-1]
    C0,C1=box.sum(axis=0).nonzero()[0][0],box.sum(axis=0).nonzero()[0][-1]
    marks=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=0 and not (R0<=r<=R1 and C0<=c<=C1):
                marks.append((r,c,inp[r][c]))
    left={m[2] for m in marks if m[1]<C0}, right={m[2] for m in marks if m[1]>C1}
    lc=list(left)[0]; rc=list(right)[0]
    h=R1-R0-1; w=C1-C0-1
    band=h//2
    out=A.copy()
    # top band: cols [C0+w//2...C1-w//2] -> left gets lc? demo: left color=4 fills left half of interior top band, right color=8 fills right half. But here left marker is 9 (left side), right marker 1 (right side). In demo, left-half filled with 4 = left marker color, right half with 8 = right marker color, bottom band swapped.
    half=w//2
    for bi in (0,1):
        for ri in range(R0+bi*band, R0+(bi+1)*band):
            for ci in range(C0, C1+1):
                if C0<=ci<C0+half: out[ri,ci]=lc
                elif C1-half<ci<=C1: out[ri,ci]=rc
                else: continue
    return out.tolist()
