    R0,R1,C0,C1=A[ys[0]:].min(),A[ys[-1]:].max(),xs.min(),xs.max()
    mks=sorted([(r,c,int(A[r,c])) for r in range(H) for c in range(W)
                if A[r,c]!=5 and A[r,c]!=0 and not(R0<=r<=R1 and C0<=c<=C1)], key=lambda x:(-x[0],x[1]))
    top=[v for _,_,v in mks]; bot=top[::-1]
    out=A.copy()
    h=R1-R0-1; b=h//2
    n=C1-C0-1; half=n//2
    for rr in range(R0+1,R0+b+1):
        for cc in range(C0+1,C0+half):   out[rr,cc]=top[0]
